#' Multi-Estimator CFA
#'
#' Fits one confirmatory factor model (one factor or several correlated 
#' factors) under several estimators and shows fit indices, loadings, factor 
#' correlations and reliabilities side by side.
#' 
#'
#' @examples
#' \donttest{
#' data('wizdata', package = 'psyWiz')
#' psyWiz::multiEstCfa(wizdata, run = TRUE, factors = list(
#'     list(label = 'Trust', vars = c('trust1', 'trust2', 'trust3', 'trust4')),
#'     list(label = 'Stress', vars = c('stress1', 'stress2', 'stress3', 'stress4'))))
#'}
#' @param data the data as a data frame
#' @param factors a list of lists, each with a \code{label} (the factor name)
#'   and \code{vars} (the names of its items)
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the planned models is shown
#' @param type \code{'auto'} (default), \code{'ordinal'} or
#'   \code{'continuous'}. ML, MLR and MLM always treat the items as continuous;
#'   the other estimators treat them as ordinal only when the items are ordinal
#' @param estML \code{TRUE} or \code{FALSE} (default), maximum likelihood
#' @param estMLR \code{TRUE} (default) or \code{FALSE}, robust maximum
#'   likelihood (Yuan-Bentler)
#' @param estMLM \code{TRUE} or \code{FALSE} (default), maximum likelihood
#'   with Satorra-Bentler correction
#' @param estULS \code{TRUE} or \code{FALSE} (default), unweighted least
#'   squares
#' @param estULSMV \code{TRUE} (default) or \code{FALSE}, unweighted least
#'   squares, mean- and variance-adjusted test
#' @param estDWLS \code{TRUE} or \code{FALSE} (default), diagonally weighted
#'   least squares
#' @param estWLSMV \code{TRUE} (default) or \code{FALSE}, diagonally weighted
#'   least squares, mean- and variance-adjusted test
#' @param estWLS \code{TRUE} or \code{FALSE} (default), weighted least squares
#'   (ADF); needs large samples
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal treatment, listwise otherwise) or \code{'listwise'}
#' @param parallel \code{TRUE} (default) or \code{FALSE}, fit the estimators
#'   concurrently when the first model takes more than a second
#' @param showStd \code{TRUE} (default) or \code{FALSE}, show the standardized
#'   loadings
#' @param showUnstd \code{TRUE} or \code{FALSE} (default), show the
#'   unstandardized loadings
#' @param sortLoadings \code{TRUE} or \code{FALSE} (default), sort the items
#'   of each factor by their mean absolute standardized loading
#' @param showCors \code{TRUE} (default) or \code{FALSE}, show the factor
#'   correlations
#' @param showRel \code{TRUE} (default) or \code{FALSE}, show composite
#'   reliability (omega) and average variance extracted for each factor
#' @param highlight \code{TRUE} or \code{FALSE} (default), show standardized
#'   loadings below 0.40 in red
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$std} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$unstd} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cors} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rel} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fit$asDF}
#'
#' \code{as.data.frame(results$fit)}
#'
#' @export
multiEstCfa <- function(
    data,
    factors = list(
                list(label="Factor 1", vars=list())),
    run = FALSE,
    type = "auto",
    estML = FALSE,
    estMLR = TRUE,
    estMLM = FALSE,
    estULS = FALSE,
    estULSMV = TRUE,
    estDWLS = FALSE,
    estWLSMV = TRUE,
    estWLS = FALSE,
    missing = "auto",
    parallel = TRUE,
    showStd = TRUE,
    showUnstd = FALSE,
    sortLoadings = FALSE,
    showCors = TRUE,
    showRel = TRUE,
    highlight = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("multiEstCfa requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- multiEstCfaOptions$new(
        factors = factors,
        run = run,
        type = type,
        estML = estML,
        estMLR = estMLR,
        estMLM = estMLM,
        estULS = estULS,
        estULSMV = estULSMV,
        estDWLS = estDWLS,
        estWLSMV = estWLSMV,
        estWLS = estWLS,
        missing = missing,
        parallel = parallel,
        showStd = showStd,
        showUnstd = showUnstd,
        sortLoadings = sortLoadings,
        showCors = showCors,
        showRel = showRel,
        highlight = highlight)

    analysis <- multiEstCfaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

